func (s *statusDayStore) CountEffectiveStudentAbsences(ctx context.Context, date careplan.Date) (careplan.StudentStatusCounts, carePlanCompose.RequestStoreStats, error) {
	students, err := s.students.ListEnrolledStudents(ctx)
	if err != nil {
		return careplan.StudentStatusCounts{}, carePlanCompose.RequestStoreStats{}, err
	}
	rows, stats, err := s.ListStudentStatusDays(ctx, careplan.StudentStatusDayFilter{Date: date, ActiveOnly: true})
	if err != nil {
		return careplan.StudentStatusCounts{}, stats, err
	}
	return countEffectiveStudentAbsences(students, statusDayFlagsByStudent(rows)), stats, nil
}

func (s *ClassArrivalExceptions) ListClassArrivalExceptions(ctx context.Context, schoolClass string, from, to calendar.Date) ([]*careplan.ClassArrivalException, error) {
	if s.store == nil {
		return nil, &careplan.ScheduleError{Op: opListClassArrivalExceptions, Err: careplan.ErrClassArrivalExceptionNotConfigured}
	}
	class := strings.TrimSpace(schoolClass)
	if class == "" {
		return []*careplan.ClassArrivalException{}, nil
	}
	rows, err := s.store.List(ctx, []string{class}, calendar.Date(from), calendar.Date(to))
	if err != nil {
		return nil, &careplan.ScheduleError{Op: opListClassArrivalExceptions, Err: err}
	}
	return rows, nil
}

