func (q offeringDayRoster) ActiveCareOfferings(ctx context.Context) ([]CareOfferingOption, error) {
	rows, err := q.records.ListCareOfferings(ctx, CareOfferingFilter{ActiveOnly: true, Order: OfferingOrderCatalog})
	if err != nil {
		return nil, fmt.Errorf("list active care offerings: %w", err)
	}
	out := make([]CareOfferingOption, 0, len(rows))
	for _, row := range rows {
		if row.IsActive && row.CountsAsCare {
			out = append(out, CareOfferingOption{ID: row.ID, Name: row.Name})
		}
	}
	return out, nil
}

func (rs *Resource) TenantRouter() chi.Router {
	router := chi.NewRouter()
	rs.runtime.Protected(router, func(protected chi.Router, withTx Middleware) {
		protected.With(withTx).Get("/", rs.status)
		protected.With(withTx).Post("/", rs.create)
		protected.With(withTx).Post("/rotate", rs.rotate)
	})
	return router
}

func (a AccessResolver) Resolve(ctx context.Context, tenantID, accountID int64) (domain.Access, error) {
	access, found, err := a.feed.ResolveAccess(ctx, tenantID, accountID)
	if err != nil || !found {
		return domain.Access{}, err
	}
	return domain.Access{Active: true, GeneralRequests: access.GeneralRequests, EnrollmentRequests: access.EnrollmentRequests, SchoolName: access.SchoolName, Subdomain: access.Subdomain}, err
}

func (s *Store) List(ctx context.Context, tenantID int64, since time.Time, access domain.Access) ([]domain.Item, error) {
	projected, err := s.feed.ListNewParentRequests(ctx, tenantID, since, access.GeneralRequests, access.EnrollmentRequests)
	if err != nil {
		return nil, fmt.Errorf("list request feed items: %w", err)
	}
	rows := make([]domain.Item, 0, len(projected))
	for _, item := range projected {
		rows = append(rows, domain.Item{Kind: item.Kind, ID: item.ID, CreatedAt: item.CreatedAt})
	}
	return rows, nil
}

func (s *Service) Status(ctx context.Context, tenantID, accountID int64) (requestfeed.Status, error) {
	if tenantID <= 0 || accountID <= 0 {
		return requestfeed.Status{}, requestfeed.ErrNotFound
	}
	if _, err := s.requireAccess(ctx, tenantID, accountID); err != nil {
		return requestfeed.Status{}, err
	}
	active, err := s.store.Active(ctx, tenantID, accountID)
	return requestfeed.Status{Active: active}, err
}
